import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("interval and duration must be greater than zero")
    records = []
    start_time = time.time()
    os_type = platform.system()
    while time.time() - start_time < duration:
        timestamp = time.time()
        if os_type == "Windows":
            try:
                output = subprocess.check_output(
                    ['typeperf', '"\\Processor(_Total)\\% Processor Time"', '-sc', '1'],
                    shell=True
                ).decode('utf-8')
                lines = output.strip().split('\n')
                if len(lines) >= 3:
                    cpu_str = lines[2].strip().split(',')[1].strip('"')
                    cpu_usage = float(cpu_str)
                else:
                    cpu_usage = 0.0
            except:
                cpu_usage = 0.0
        else:
            try:
                output = subprocess.check_output(
                    ['top', '-bn1']
                ).decode('utf-8')
                for line in output.split('\n'):
                    if 'Cpu(s)' in line:
                        idle = float(line.split(',')[3].strip().replace('id', ''))
                        cpu_usage = 100.0 - idle
                        break
                else:
                    cpu_usage = 0.0
            except:
                cpu_usage = 0.0
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(records, f)
    except IOError:
        return None
    return LOGFILE_PATH
